<?php require_once 'config.php'; require_login(); $pdo=db(); $uid=$_SESSION['user']['id'];
$stmt=$pdo->prepare('SELECT dt.id AS daily_id,t.title,t.icon,t.points,s.id submission_id,s.status,s.admin_note FROM daily_tasks dt JOIN tasks t ON t.id=dt.task_id LEFT JOIN submissions s ON s.daily_task_id=dt.id WHERE dt.user_id=? AND dt.assigned_on=CURDATE()');$stmt->execute([$uid]);$quest=$stmt->fetch(); if (!$quest) redirect('dashboard.php');
if ($_SERVER['REQUEST_METHOD']==='POST') { if (!isset($_FILES['proof']) || $_FILES['proof']['error']!==UPLOAD_ERR_OK || !in_array(mime_content_type($_FILES['proof']['tmp_name']),['image/jpeg','image/png','image/webp'],true)) { flash('error','Please upload a JPG, PNG, or WebP photo.');redirect('submit.php'); }
  $dir='uploads';if(!is_dir($dir)) mkdir($dir,0755,true);$extension=pathinfo($_FILES['proof']['name'],PATHINFO_EXTENSION);$path=$dir.'/'.bin2hex(random_bytes(10)).'.'.strtolower($extension);move_uploaded_file($_FILES['proof']['tmp_name'],$path);
  $pdo->prepare('INSERT INTO submissions (daily_task_id,description,image_path) VALUES (?,?,?) ON DUPLICATE KEY UPDATE description=VALUES(description),image_path=VALUES(image_path),status="pending",admin_note=NULL')->execute([$quest['daily_id'],trim($_POST['description']??''),$path]);flash('success','Your positive act is on its way to review.');redirect('dashboard.php');
} require 'header.php'; ?>
<section class="submission"><a class="back" href="dashboard.php">← Back to my quest</a><div class="submission-grid"><div><p class="eyebrow">Share your ripple</p><h1><?= esc($quest['title']) ?></h1><p class="lead">A photo and a few words help us celebrate the impact you made.</p><div class="mini-quest"><i><?= esc($quest['icon']) ?></i><span><b><?= esc($quest['title']) ?></b><small>Worth <?= (int)$quest['points'] ?> points</small></span></div><?php if ($quest['status']==='rejected'): ?><p class="review-note"><b>Reviewer note:</b> <?= esc($quest['admin_note']) ?></p><?php endif; ?></div><form class="proof-form" method="post" enctype="multipart/form-data"><label class="upload" id="upload-area"><input required type="file" accept="image/jpeg,image/png,image/webp" name="proof"><span class="upload-icon">↑</span><b>Upload a photo</b><small>JPG, PNG, or WebP · up to your server limit</small></label><label>Tell the story<textarea required name="description" maxlength="1000" placeholder="What did you do? Who did it help?"></textarea></label><button class="button" type="submit">Send for review →</button></form></div></section>
